style.css:
@-moz-document domain("google.com") {
/* Hatsune Miku Theme for Google - Cyan, Pink & White Vocaloid Magic! */
  
  /* Background gradient with Miku's signature cyan */
  body {
    background: linear-gradient(135deg, #00d4ff 0%, #39d5ff 25%, #fff 50%, #ff9ed5 75%, #ff6ec7 100%) !important;
    background-attachment: fixed !important;
  }
  
  /* Google logo area with cyan glow */
  #logo, .logo, img[alt="Google"] {
    filter: drop-shadow(0 0 10px #00ffff) drop-shadow(0 0 20px #ff69b4) !important;
    border-radius: 15px !important;
    padding: 10px !important;
    background: rgba(255, 255, 255, 0.9) !important;
  }
  
  /* Search box with Miku colors */
  input[type="text"], textarea, .gLFyf, .a4bIc {
    background: rgba(255, 255, 255, 0.95) !important;
    border: 3px solid #00d4ff !important;
    border-radius: 25px !important;
    box-shadow: 0 4px 15px rgba(0, 212, 255, 0.4), inset 0 2px 5px rgba(255, 105, 180, 0.2) !important;
    color: #333 !important;
  }
  
  /* Search box on focus - pink glow */
  input[type="text"]:focus, textarea:focus, .gLFyf:focus {
    border-color: #ff69b4 !important;
    box-shadow: 0 0 20px #ff69b4, 0 0 30px #00ffff !important;
    outline: none !important;
  }
  
  /* Search buttons with vocaloid style */
  input[type="submit"], button, .gNO89b, .Tg7LZd {
    background: linear-gradient(to bottom, #00d4ff, #0099cc) !important;
    border: 2px solid #fff !important;
    border-radius: 20px !important;
    color: white !important;
    font-weight: bold !important;
    box-shadow: 0 4px 10px rgba(0, 212, 255, 0.5) !important;
    transition: all 0.3s ease !important;
  }
  
  button:hover, input[type="submit"]:hover, .gNO89b:hover {
    background: linear-gradient(to bottom, #ff69b4, #ff1493) !important;
    box-shadow: 0 6px 15px rgba(255, 105, 180, 0.6) !important;
    transform: translateY(-2px) !important;
  }
  
  /* Link styling with cyan accent */
  a {
    color: #0099cc !important;
    text-decoration: none !important;
    transition: color 0.2s ease !important;
  }
  
  a:hover {
    color: #ff69b4 !important;
    text-shadow: 0 0 8px rgba(255, 105, 180, 0.5) !important;
  }
  
  /* Headers with Miku pink */
  h1, h2, h3 {
    color: #ff69b4 !important;
    text-shadow: 1px 1px 2px rgba(0, 212, 255, 0.3) !important;
  }
  
  /* Add cute borders and accents */
  .sfbg, .minidiv, div[class*="container"] {
    border: 2px solid rgba(0, 212, 255, 0.3) !important;
    border-radius: 15px !important;
    background: rgba(255, 255, 255, 0.85) !important;
  }
  
  /* Navigation and top bar */
  #gb, .gb_Xe, header {
    background: linear-gradient(to right, #00d4ff, #39d5ff, #ff9ed5) !important;
    box-shadow: 0 2px 10px rgba(0, 212, 255, 0.5) !important;
  }
  
  /* Add sparkle effect to elements */
  .s, .st, .rc {
    background: rgba(255, 255, 255, 0.9) !important;
    border-left: 4px solid #00d4ff !important;
    border-radius: 10px !important;
    padding: 10px !important;
    margin: 10px 0 !important;
    box-shadow: 2px 2px 8px rgba(255, 105, 180, 0.2) !important;
  }
  
  /* Footer with vocaloid colors */
  footer, .fbar {
    background: linear-gradient(to right, #00d4ff, #ff69b4) !important;
    color: white !important;
    border-top: 3px solid white !important;
  }
  
  /* Special Miku accent - add cyan border to main content */
  #main, #center_col, #rso {
    padding: 20px !important;
    background: rgba(255, 255, 255, 0.7) !important;
    border-radius: 20px !important;
    border: 3px dashed rgba(0, 212, 255, 0.4) !important;
  }
}
